-- ----------------------------
-- Table structure for hyn_sys_online_session
-- ----------------------------
DROP TABLE IF EXISTS `hyn_sys_online_session`;
CREATE TABLE `hyn_sys_online_session`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键，自增',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会话id',
  `authorization_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '授权记录id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `principal_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `client_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户端id',
  `grant_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '授权模式',
  `ip_address` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP 地址',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '地址',
  `user_agent` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户代理',
  `browser` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '浏览器',
  `browser_version` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '浏览器版本',
  `os_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作系统名称',
  `login_time` datetime NOT NULL COMMENT '登录时间',
  `last_active_time` datetime NULL DEFAULT NULL COMMENT '最后活动时间',
  `access_token_expires_at` datetime NULL DEFAULT NULL COMMENT '访问令牌过期时间',
  `refresh_token_expires_at` datetime NULL DEFAULT NULL COMMENT '刷新令牌过期时间',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态（0=离线，1=在线）',
  `logout_time` datetime NULL DEFAULT NULL COMMENT '退出登录时间',
  `logout_reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退出登录原因',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_online_session_session_id`(`session_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_online_session_authorization_id`(`authorization_id` ASC) USING BTREE,
  INDEX `idx_online_session_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_online_session_status_active`(`status` ASC, `last_active_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

